  var KEY = "miniringle-language-choice";
  function supported(code) { for (var i = 0; i < LANGS.length; i++) if (LANGS[i][0] === code) return true; return false; }
  // 영어 글을 그 언어로(없으면 영어 그대로).
  function t(lang, en) { var d = T[lang]; return d && d[en] ? d[en] : en; }
  // 링크의 lang → 저장한 고른 언어 → 영어.
  function initial(query) {
    if (supported(query)) return query;
    var saved = null;
    try { saved = localStorage.getItem(KEY); } catch (e) {}
    return supported(saved) ? saved : "en";
  }
  // 한국어는 ko 글, 나머지는 en 글을 보이고 en 글을 그 언어로 바꾼다(원래 영어 글은 data-en에 둔다).
  function apply(lang) {
    var root = document.documentElement;
    root.setAttribute("data-lang", lang === "ko" ? "ko" : "en");
    root.setAttribute("lang", lang);
    document.querySelectorAll("body [lang=\"en\"]").forEach(function (el) {
      if (el.tagName === "IMG") return;
      if (el.getAttribute("data-en") === null) el.setAttribute("data-en", el.textContent);
      el.textContent = t(lang, el.getAttribute("data-en"));
    });
    document.querySelectorAll("[data-lang-select]").forEach(function (s) { s.value = lang; });
  }
  // 고르기 상자를 채우고, 고르면 apply · 저장 · onChange.
  function bind(onChange) {
    document.querySelectorAll("[data-lang-select]").forEach(function (s) {
      LANGS.forEach(function (l) { var o = document.createElement("option"); o.value = l[0]; o.textContent = l[1]; s.appendChild(o); });
      s.addEventListener("change", function () {
        apply(s.value);
        try { localStorage.setItem(KEY, s.value); } catch (e) {}
        if (onChange) onChange(s.value);
      });
    });
  }
  // 점수 페이지 단위(win · floor · floor1). 한국어 · 영어는 페이지가 직접 쓴다.
  function unit(lang, key) { var d = U[lang]; return d ? d[key] : null; }
  window.MiniRingleI18n = { t: t, initial: initial, apply: apply, bind: bind, unit: unit };
